from torch.utils.data import Dataset, DataLoader
class  data(Dataset):
    def __init__(self , X,Y,vs , padsz):
        self.X = X
        self.Y = Y
        self.vocab_size = vs
        self.mx = padsz
    def __len__(self):
        return len(self.X)
    def __getitem__(self , index):
        _x = self.X[index]
        _y = self.Y[index]

        # Truncate or pad x to self.mx length
        if len(_x) > self.mx:
            _x = _x[:self.mx]
            _y = _y[:self.mx]
        else:
            # Pad with zeros
            x_pad_len = self.mx - len(_x)
            _x = F.pad(_x, (0, x_pad_len))
            _y = F.pad(_y, (0, x_pad_len))

        # Create one-hot encoded y
        _y_onehot = torch.zeros((self.mx, self.vocab_size))
        _y_onehot[torch.arange(self.mx), _y.long()] = 1

        return _x.long(), _y_onehot.long()

class sentimentdata(Dataset):
    def __init__(self , X,Y , padsz=40):
        self.X = X
        self.Y = Y
        self.mx = padsz
    def __len__(self):
        return len(self.X)
    def __getitem__(self , index):
